import 'dart:typed_data';

import 'package:test/test.dart';
import 'package:zuraffa/zuraffa.dart';
import 'package:zuraffa_purchase/zuraffa_purchase.dart';

class _RecordingPort implements PurchasePort {
  final List<String> calls = [];

  @override
  Future<bool> isSupported() async {
    calls.add('isSupported');
    return true;
  }

  @override
  Future<PurchaseModule> compile({
    required String id,
    required Uint8List bytes,
  }) async {
    calls.add('compile:$id');
    return PurchaseModule(id: id, byteLength: bytes.lengthInBytes);
  }

  @override
  Future<List<PurchaseValue>> invoke({
    required String id,
    required String export,
    List<PurchaseValue> args = const [],
  }) async {
    calls.add('invoke:$id:$export');
    return [const PurchaseI32(42)];
  }

  @override
  Future<void> unload({required String id}) async {
    calls.add('unload:$id');
  }
}

void main() {
  group('PurchaseService', () {
    late _RecordingPort port;
    late PurchaseService service;

    setUp(() {
      port = _RecordingPort();
      service = PurchaseService(port: port);
    });

    test('compile registers the module and call routes through the port',
        () async {
      final module = await service.compile(
        id: 'demo',
        bytes: Uint8List.fromList([1, 2, 3]),
      );

      expect(module.byteLength, 3);
      expect(service.compiledModules, contains('demo'));

      final results = await service.call(
        id: 'demo',
        export: 'run',
        args: const [PurchaseI32(1)],
      );

      expect(port.calls, contains('invoke:demo:run'));
      expect(results.single, isA<PurchaseI32>());
      expect((results.single as PurchaseI32).value, 42);
    });

    test('call before compile surfaces the typed not_compiled failure',
        () async {
      await expectLater(
        service.call(id: 'missing', export: 'run'),
        throwsA(
          isA<PurchaseException>()
              .having((e) => e.code, 'code', 'not_compiled')
              .having((e) => e.recoverable, 'recoverable', isFalse),
        ),
      );
    });

    test('double compile surfaces already_compiled', () async {
      await service.compile(id: 'demo', bytes: Uint8List(0));

      await expectLater(
        service.compile(id: 'demo', bytes: Uint8List(0)),
        throwsA(
          isA<PurchaseException>()
              .having((e) => e.code, 'code', 'already_compiled'),
        ),
      );
    });

    test('unload releases the module and further calls fail typed',
        () async {
      await service.compile(id: 'demo', bytes: Uint8List(0));
      await service.unload(id: 'demo');

      expect(service.compiledModules, isNot(contains('demo')));
      await expectLater(
        service.call(id: 'demo', export: 'run'),
        throwsA(isA<PurchaseException>()),
      );
    });

    test('registration without a port surfaces typed port_not_wired',
        () async {
      final getIt = GetIt.instance;
      await getIt.reset();
      registerPurchaseDependencies(getIt);

      final service = getIt<PurchaseService>();
      await expectLater(
        service.supported(),
        throwsA(
          isA<PurchaseException>()
              .having((e) => e.code, 'code', 'port_not_wired'),
        ),
      );
    });

    test('registration with a port binds the service to it', () async {
      final getIt = GetIt.instance;
      await getIt.reset();
      registerPurchaseDependencies(getIt, port: _RecordingPort());

      expect(await getIt<PurchaseService>().supported(), isTrue);
    });
  });

  group('PurchaseValue', () {
    test('round-trips through the channel encoding', () {
      final i32 = PurchaseValue.decode(PurchaseI32(7).encode());
      expect(i32, isA<PurchaseI32>());

      final i64 = PurchaseValue.decode(
        PurchaseI64(BigInt.parse('9007199254740993')).encode(),
      );
      expect((i64 as PurchaseI64).value, BigInt.parse('9007199254740993'));

      final f64 = PurchaseValue.decode(PurchaseF64(1.5).encode());
      expect((f64 as PurchaseF64).value, 1.5);
    });

    test('rejects payloads it cannot decode', () {
      expect(
        () => PurchaseValue.decode(const [1, 2, 3]),
        throwsA(
          isA<PurchaseException>()
              .having((e) => e.code, 'code', 'malformed_value'),
        ),
      );
    });
  });
}
